const root=document.querySelector('#root'),groups=document.querySelector('#groups'),outline=document.querySelector('#outline'),reading=document.querySelector('#reading'),language=document.querySelector('#language');
const nodes=[];
function syncGlobal(){language.textContent=nodes.length&&nodes.every(b=>b.dataset.en==='true')?'全部恢复中文':'全部切换为英文';}
function setLanguage(button,en){button.dataset.en=String(en);button.classList.toggle('en',en);button.querySelector('.sentence').textContent=en?button.item.en:button.item.zh;button.querySelector('.sentence').lang=en?'en':'zh-CN';button.querySelector('.switch-hint').textContent=en?'点击看中文':'点击看英文原段';button.setAttribute('aria-pressed',String(en));button.title=en?'点击恢复中文':'点击查看对应英文原段';syncGlobal();}
function makeNode(item){const b=document.createElement('button');b.className='sentence-node';b.id=item.id;b.item=item;const sentence=document.createElement('span');sentence.className='sentence';const meta=document.createElement('span');meta.className='metadata';const reference=document.createElement('span');reference.className='reference';reference.textContent=`${item.role} · 原文第 ${item.paragraph} 段`;const hint=document.createElement('span');hint.className='switch-hint';meta.append(reference,hint);b.append(sentence,meta);nodes.push(b);setLanguage(b,false);b.onclick=()=>setLanguage(b,b.dataset.en!=='true');return b;}
function navigateTo(id){const target=document.getElementById(id);if(!target)return;target.scrollIntoView({block:'start',behavior:'instant'});document.querySelectorAll('#outline a').forEach(a=>a.setAttribute('aria-current',String(a.getAttribute('href')==='#'+id)));}
language.onclick=()=>{const en=!nodes.every(b=>b.dataset.en==='true');nodes.forEach(b=>setLanguage(b,en));};
fetch('article-data.json?v=full-1').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json();}).then(data=>{
root.append(makeNode(data.root));
const makeLink=(label,id,number)=>{const a=document.createElement('a');a.href='#'+id;const n=document.createElement('span');n.className='number';n.textContent=number;const name=document.createElement('span');name.textContent=label;a.append(n,name);a.onclick=e=>{e.preventDefault();navigateTo(id);};outline.append(a);return a;};
makeLink('中心问题','question','');
data.groups.forEach((g,i)=>{const section=document.createElement('section');section.className='group';section.id=g.id;const heading=document.createElement('div');heading.className='group-heading';const num=document.createElement('span');num.className='number';num.textContent=String(i+1).padStart(2,'0');const h=document.createElement('h2');h.textContent=g.label;heading.append(num,h);const explanation=document.createElement('p');explanation.className='analysis';explanation.textContent=g.analysis;const content=document.createElement('div');content.className='group-content';const main=document.createElement('div');main.className='main-node';main.append(makeNode(g.main));const evidence=document.createElement('div');evidence.className='evidence';g.evidence.forEach(item=>evidence.append(makeNode(item)));content.append(main,evidence);section.append(heading,explanation,content);groups.append(section);makeLink(g.label,g.id,num.textContent);});
const c=data.coverage;document.querySelector('#coverage').textContent=`正文 ${c.coveredParagraphs} / ${c.bodyParagraphs} 段 · ${c.bodyWords} 词`;document.querySelector('#coverageCount').textContent=`${c.coveredParagraphs} / ${c.bodyParagraphs} 段`;
data.paragraphs.forEach(p=>{const a=document.createElement('a');a.href='#'+p.id;a.textContent=`第 ${p.paragraph} 段`;a.title=p.zh;a.onclick=e=>{e.preventDefault();navigateTo(p.id);document.getElementById(p.id).focus({preventScroll:true});};document.querySelector('#paragraphIndex').append(a);});
language.disabled=false;
const sections=[document.querySelector('#question'),...document.querySelectorAll('.group')];
const updateActive=()=>{let current=sections[0];if(reading.scrollTop+reading.clientHeight>=reading.scrollHeight-3){current=sections.at(-1);}else{const top=reading.getBoundingClientRect().top+120;for(const s of sections){if(s.getBoundingClientRect().top<=top)current=s;else break;}}document.querySelectorAll('#outline a').forEach(a=>a.setAttribute('aria-current',String(a.getAttribute('href')==='#'+current.id)));};
reading.addEventListener('scroll',updateActive,{passive:true});updateActive();
}).catch(e=>{const error=document.querySelector('#error');error.hidden=false;error.textContent='全文暂未加载，请刷新重试。'+e.message;document.querySelector('#coverage').textContent='未能读取全文';});
